import logging, time, os
import click
from click.shell_completion import _resolve_context

logging.basicConfig(level=logging.WARNING, format="LOG: %(levelname)s %(name)s: %(message)s")

@click.group()
@click.option("--x", is_eager=True, callback=lambda ctx, param, value: (ctx.call_on_close(lambda: time.sleep(30)), value)[1])
def cli(x):
    pass

@cli.command()
def sub():
    pass

# 1) WITH cleanup_timeout: must not hang
t0 = time.monotonic()
ctx = _resolve_context(cli, {"cleanup_timeout": 1.0}, "cli", ["sub"])
dt = time.monotonic() - t0
print(f"1) completion with timeout returned in {dt:.2f}s")
assert dt < 10, dt
assert ctx.cleanup_timeout == 1.0

# 2) without timeout but fast cleanup: completion still works
@click.group()
def cli2():
    pass

@cli2.command()
def sub2():
    pass

words_ctx = _resolve_context(cli2, {}, "cli2", [])
print("2) plain completion ok:", words_ctx.command.name)

# 3) full shell_complete via runner with env + cleanup_timeout extra
from click.testing import CliRunner
runner = CliRunner()

@click.command()
@click.option("--y", is_eager=True, callback=lambda ctx, param, value: (ctx.call_on_close(lambda: time.sleep(30)), value)[1])
@click.argument("text")
def prog(y, text):
    pass

env = {"COMP_WORDS": "prog ", "COMP_CWORD": "1", "_PROG_COMPLETE": "bash_complete"}
t0 = time.monotonic()
result = runner.invoke(prog, env=env, cleanup_timeout=1.0)
dt = time.monotonic() - t0
print(f"3) runner.invoke completion with timeout in {dt:.2f}s; output={result.output!r}; exc={result.exception!r}")
assert dt < 15, dt
EOF

